    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  const handlers: Record<string, (ctx: Ctx, e: Record<string, unknown>, i: number) => string | null> = {
    order: doOrder,
    cancel: doCancel,
    ship: doShip,
    restock: doRestock,
    expire: doExpire,
  };

  const validations: Record<string, Array<"id" | "item" | "qty">> = {
    order: ["id", "item", "qty"],
    cancel: ["id"],
    ship: ["id", "qty"],
    restock: ["item", "qty"],
    expire: ["id"],
  };

