interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type Ctx = {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
};

/** Stock on hand for an item, treating "not tracked" as zero. */
function held(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

/** Return an order's reservation to stock, recording its final status. */
function release(ctx: Ctx, id: string, status: "cancelled" | "expired"): void {
  const holding = ctx.reserved[id];
  ctx.stock[holding.item] = held(ctx.stock, holding.item) + holding.qty;
  delete ctx.reserved[id];
  ctx.orders[id] = status;
  backfill(ctx);
}

/** Fulfil waiting backorders as far as current stock allows. */
function backfill(ctx: Ctx): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = held(ctx.stock, want.item);
    if (onHand < want.qty) {
      continue;
    }
    ctx.stock[want.item] = onHand - want.qty;
    ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
    ctx.orders[pendingId] = "reserved";
    delete ctx.pendingWants[pendingId];
    ctx.queue.splice(position, 1);
    position = position - 1;
  }
}

function doOrder(ctx: Ctx, event: Record<string, unknown>, index: number): string | null {
  const qty = event.qty;
  if (held(ctx.stock, event.item as string) >= (qty as number)) {
    ctx.stock[event.item as string] = held(ctx.stock, event.item as string) - (qty as number);
    ctx.reserved[event.id as string] = { item: event.item as string, qty: qty as number };
    ctx.orders[event.id as string] = "reserved";
  } else {
    ctx.queue.push(event.id as string);
    ctx.pendingWants[event.id as string] = { item: event.item as string, qty: qty as number };
    ctx.orders[event.id as string] = "backordered";
  }
  return null;
}

function doCancel(ctx: Ctx, event: Record<string, unknown>): string | null {
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    release(ctx, id, "cancelled");
  } else if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function doShip(ctx: Ctx, event: Record<string, unknown>): string | null {
  const id = event.id as string;
  const reservation = ctx.reserved[id];
  if (reservation === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === reservation.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
  } else if ((event.qty as number) < reservation.qty) {
    reservation.qty = reservation.qty - (event.qty as number);
    ctx.orders[id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function doRestock(ctx: Ctx, event: Record<string, unknown>): string | null {
  ctx.stock[event.item as string] =
    held(ctx.stock, event.item as string) + (event.qty as number);
  backfill(ctx);
  return null;
}

function doExpire(ctx: Ctx, event: Record<string, unknown>): string | null {
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    release(ctx, id, "expired");
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const ctx: Ctx = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  const handlers: Record<string, (ctx: Ctx, e: Record<string, unknown>, i: number) => string | null> = {
    order: doOrder,
    cancel: doCancel,
    ship: doShip,
    restock: doRestock,
    expire: doExpire,
  };

  const validations: Record<string, Array<"id" | "item" | "qty">> = {
    order: ["id", "item", "qty"],
    cancel: ["id"],
    ship: ["id", "qty"],
    restock: ["item", "qty"],
    expire: ["id"],
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    const fields = validations[event.type as string];
    if (fields === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    for (const field of fields) {
      const value = event[field];
      if (field === "id" || field === "item") {
        if (typeof value !== "string" || value.length === 0) {
          return { ok: false, error: "event " + index + ": bad " + field };
        }
      } else if (value === undefined && event.type === "ship") {
        continue; // qty is optional on a ship
      } else if (!Number.isInteger(value) || (value as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
    }
    if (event.type === "order" && ctx.orders[event.id as string] !== undefined) {
      return { ok: false, error: "event " + index + ": duplicate order" };
    }

    const error = handlers[event.type as string](ctx, event, index);
    if (error !== null) {
      return { ok: false, error: error };
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

